WITH src AS (SELECT *, FLOOR(duration_sec) AS duration_sec_whole FROM web_events WHERE event_type IN ('click', 'page_view')), summary AS (SELECT MONTH(event_time) AS event_month, COUNT(DISTINCT duration_sec) AS unique_event_types, ROUND((100 * SUM(CASE WHEN event_type = 'search' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_search FROM src GROUP BY MONTH(event_time)) SELECT * FROM summary WHERE unique_event_types >= 6 ORDER BY pct_search DESC;
